-- Q7 [Sigma/Pi Bonds & Hybridization · medium · Skill 2 · general-chemistry · ans C] (g73)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Sigma/Pi Bonds & Hybridization',
    $qt73$Formaldehyde, \(\text{H}_2\text{C}=\text{O}\), has both \(\text{C}-\text{H}\) bonds and the \(\text{C}=\text{O}\) bond emanating from a single \(sp^2\) carbon. Counting every bond in the molecule, which tally of sigma and pi bonds is correct?$qt73$,
    $op73$[{"label":"A","text":"\\(2\\) sigma bonds and \\(2\\) pi bonds"},{"label":"B","text":"\\(4\\) sigma bonds and \\(0\\) pi bonds"},{"label":"C","text":"\\(3\\) sigma bonds and \\(1\\) pi bond"},{"label":"D","text":"\\(1\\) sigma bond and \\(3\\) pi bonds"}]$op73$::jsonb,
    'C',
    $ex73$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is C because each of the two \(\text{C}-\text{H}\) single bonds is one sigma bond, and the \(\text{C}=\text{O}\) double bond consists of one sigma bond plus one pi bond, giving \(3\) sigma and \(1\) pi total. Any single covalent bond is a sigma bond formed by head-on orbital overlap; a double bond is one sigma bond plus one pi bond, where the pi bond arises from side-on overlap of the unhybridized \(p\) orbitals on carbon and oxygen, so the molecule contains \(2 + 1 = 3\) sigma bonds and exactly \(1\) pi bond. (Choice A) Counting \(2\) sigma and \(2\) pi treats only the double bond as the source of sigma bonds and assigns the \(\text{C}-\text{H}\) bonds to the pi category, but single bonds are always sigma bonds, not pi bonds. (Choice B) Counting \(4\) sigma and \(0\) pi correctly identifies four bonding connections as containing a sigma component but ignores the pi bond that must accompany the sigma bond within the \(\text{C}=\text{O}\) double bond. (Choice D) Counting \(1\) sigma and \(3\) pi reverses the roles of single and multiple bonds, treating each line in the structure as a pi bond and recognizing only one sigma bond, whereas every bond has a sigma component and only the double bond adds a pi. Skill 2$ex73$,
    'medium', '5B', $cc73$Nature of molecules and intermolecular interactions$cc73$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a73A$Counts the pi bond from the double bond but miscounts single bonds as pi bonds, keeping only the double bond's sigma$a73A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a73B$Counts every bonding connection as sigma but omits the additional pi bond inside the C=O double bond$a73B$ FROM q
