-- Q9 [Intermolecular Forces · easy · Skill 1 · general-chemistry · ans A] (g75)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Intermolecular Forces',
    $qt75$In liquid hydrogen fluoride, \(\text{HF}\), each molecule holds one \(\text{H}\) atom bonded directly to \(\text{F}\). Which intermolecular force most likely dominates the attractions between neighboring \(\text{HF}\) molecules?$qt75$,
    $op75$[{"label":"A","text":"Hydrogen bonding, because \\(\\text{H}\\) is bonded to the highly electronegative \\(\\text{F}\\) atom"},{"label":"B","text":"Dipole-dipole attraction, with no hydrogen bonding present because \\(\\text{HF}\\) has only one \\(\\text{H}\\) atom"},{"label":"C","text":"London dispersion forces, because \\(\\text{HF}\\) is a small, easily polarizable molecule"},{"label":"D","text":"Hydrogen bonding, because the \\(\\text{H}\\)-\\(\\text{F}\\) covalent bond itself links one molecule to the next"}]$op75$::jsonb,
    'A',
    $ex75$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is A because the \(\text{H}\) atom in \(\text{HF}\) is bonded to fluorine, one of the three highly electronegative atoms (\(\text{N}\), \(\text{O}\), \(\text{F}\)) whose direct bond to hydrogen produces hydrogen bonding. A hydrogen bond is the strong attraction between an \(\text{H}\) covalently bonded to \(\text{N}\), \(\text{O}\), or \(\text{F}\) and a lone pair on an electronegative atom of a neighboring molecule; the large \(\Delta\text{EN}\) of the \(\text{H}-\text{F}\) bond leaves the \(\text{H}\) strongly partially positive and the \(\text{F}\) strongly partially negative with available lone pairs, so the dominant attraction between \(\text{HF}\) molecules is hydrogen bonding, which is far stronger than ordinary dipole-dipole or dispersion attractions in a molecule this small. (Choice B) Dipole-dipole attraction is present in \(\text{HF}\), but hydrogen bonding is a specific, much stronger subset of dipole-dipole interaction that occurs precisely because \(\text{H}\) is bonded to \(\text{F}\); having only one \(\text{H}\) per molecule does not prevent hydrogen bonding, so naming plain dipole-dipole as dominant understates the controlling force. (Choice C) London dispersion forces act in every molecule but are weak for a small molecule like \(\text{HF}\) and are overwhelmed by the much stronger hydrogen bonding arising from the \(\text{H}-\text{F}\) bond. (Choice D) Hydrogen bonding is correctly named, but it is an intermolecular attraction between separate molecules, not the intramolecular \(\text{H}-\text{F}\) covalent bond that holds a single molecule together. Skill 1$ex75$,
    'easy', '5B', $cc75$Nature of molecules and intermolecular interactions$cc75$, 'general-chemistry', 1, 75
  ) RETURNING id
)
