-- Q10 [Intermolecular Forces · medium · Skill 2 · general-chemistry · ans D] (g76)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Intermolecular Forces',
    $qt76$A flask holds a mixture of the monatomic noble gases \(\text{He}\), \(\text{Ne}\), \(\text{Ar}\), and \(\text{Xe}\), where the only operative intermolecular force is London dispersion. Ranking these gases from lowest to highest normal boiling point most likely gives which order?$qt76$,
    $op76$[{"label":"A","text":"\\(\\text{Xe} < \\text{Ar} < \\text{Ne} < \\text{He}\\)"},{"label":"B","text":"\\(\\text{Ne} < \\text{He} < \\text{Ar} < \\text{Xe}\\)"},{"label":"C","text":"\\(\\text{He} < \\text{Ne} < \\text{Xe} < \\text{Ar}\\)"},{"label":"D","text":"\\(\\text{He} < \\text{Ne} < \\text{Ar} < \\text{Xe}\\)"}]$op76$::jsonb,
    'D',
    $ex76$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is D because boiling point rises with the strength of London dispersion forces, and dispersion strength increases with atomic size and polarizability in the order \(\text{He} < \text{Ne} < \text{Ar} < \text{Xe}\). For nonpolar monatomic species, the only intermolecular attraction available is the London dispersion force, which arises from instantaneous, fluctuating dipoles in the electron cloud. A larger atom holds more electrons in a larger, more loosely held cloud, so it is more polarizable; this produces stronger instantaneous induced dipoles, greater interatomic attraction, and a higher temperature required to overcome those attractions and boil. Down the noble-gas series \(\text{He} \to \text{Ne} \to \text{Ar} \to \text{Xe}\), atomic radius and electron count both grow, so dispersion strength and therefore boiling point increase monotonically. (Choice A) This is the exact reverse of the correct trend, treating the smallest, least polarizable atom as having the strongest dispersion forces and highest boiling point. (Choice B) This places \(\text{Ne}\) below \(\text{He}\), which inverts the size/polarizability relationship for that pair while keeping the rest of the order intact; \(\text{Ne}\) is larger and more polarizable than \(\text{He}\) and therefore boils higher. (Choice C) This swaps \(\text{Ar}\) and \(\text{Xe}\), ranking the smaller \(\text{Ar}\) above the larger \(\text{Xe}\); because \(\text{Xe}\) has the most electrons and the greatest polarizability, it has the strongest dispersion forces and the highest boiling point. Skill 2$ex76$,
    'medium', '5B', $cc76$Nature of molecules and intermolecular interactions$cc76$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a76A$Inverts the polarizability-boiling point relationship, ranking the smallest atom highest$a76A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a76B$Confuses relative size/polarizability of the He-Ne pair, placing the smaller atom above the larger$a76B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a76C$Correct general trend but transposes the two heaviest atoms (Ar above Xe)$a76C$ FROM q;

-- Q11 [Intermolecular Forces · medium · Skill 2 · general-chemistry · ans B] (g77)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Intermolecular Forces',
    $qt77$Chloromethane \(\text{CH}_3\text{Cl}\) (molar mass \(50.5\ \text{g/mol}\)) boils at \(-24\,^\circ\text{C}\), well above propane \(\text{C}_3\text{H}_8\) (molar mass \(44\ \text{g/mol}\)) at \(-42\,^\circ\text{C}\). Given that neither molecule has hydrogen bonded to N, O, or F, which intermolecular force accounts for the elevated boiling point of \(\text{CH}_3\text{Cl}\)?$qt77$,
    $op77$[{"label":"A","text":"Hydrogen bonding, because the C–H bonds in \\(\\text{CH}_3\\text{Cl}\\) act as hydrogen-bond donors to the chlorine lone pairs of neighboring molecules"},{"label":"B","text":"Dipole–dipole forces, because the net molecular dipole of \\(\\text{CH}_3\\text{Cl}\\) lets neighboring molecules align oppositely-charged ends, adding attraction beyond dispersion alone"},{"label":"C","text":"London dispersion forces, because the larger, more polarizable electron cloud of \\(\\text{CH}_3\\text{Cl}\\) is the only force present in both molecules"},{"label":"D","text":"Ion–dipole forces, because the polar C–Cl bond places a full negative charge on chlorine that attracts the partial positive ends of neighbors"}]$op77$::jsonb,
    'B',
    $ex77$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is B because \(\text{CH}_3\text{Cl}\) is a polar molecule whose permanent net dipole permits dipole-dipole attraction between molecules, an extra cohesive force that nonpolar propane lacks. Both molecules experience London dispersion forces of roughly comparable strength given their similar molar masses, so dispersion cannot explain the higher boiling point; the difference comes from the additional dipole-dipole attraction in \(\text{CH}_3\text{Cl}\), where the polar \(\text{C-Cl}\) bond produces a molecular dipole pointing toward chlorine, letting the partial-negative \(\text{Cl}\) end of one molecule align with the partial-positive end of a neighbor and raising the energy needed to separate molecules into the gas phase. (Choice A) Hydrogen bonding requires hydrogen covalently bonded to N, O, or F; \(\text{CH}_3\text{Cl}\) has only \(\text{C-H}\) bonds, so it cannot serve as a hydrogen-bond donor regardless of chlorine's lone pairs. (Choice C) London dispersion forces are present in both molecules and are similar in magnitude here because the molar masses are close, so dispersion alone does not distinguish the two boiling points; it ignores the permanent dipole unique to the polar molecule. (Choice D) Ion-dipole forces require an actual ion, but the \(\text{C-Cl}\) bond is polar covalent and bears only a partial negative charge on chlorine, not a full ionic charge, so no ion-dipole interaction exists between neutral \(\text{CH}_3\text{Cl}\) molecules. Skill 2$ex77$,
    'medium', '5B', $cc77$Nature of molecules and intermolecular interactions$cc77$, 'general-chemistry', 2, 110
  ) RETURNING id
)
