UNION ALL SELECT id, 'D', 'scale_unit_error', $a78D$molar mass treated as boosting dipole-dipole rather than dispersion forces$a78D$ FROM q;

-- Q13 [Intermolecular Forces · hard · Skill 2 · general-chemistry · ans A] (g79)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Intermolecular Forces',
    $qt79$A sealed flask of liquid \(\text{H}_2\text{O}\) is cooled until it freezes solid, and the resulting ice (density \(\approx 0.92\ \text{g/cm}^3\)) is observed to float in the remaining liquid water (density \(\approx 1.0\ \text{g/cm}^3\)). Given that hydrogen bonding dominates the intermolecular interactions in both phases, the lower density of the solid is best explained by which structural consequence of those hydrogen bonds?$qt79$,
    $op79$[{"label":"A","text":"On freezing, hydrogen bonds lock the \\(\\text{H}_2\\text{O}\\) molecules into a more open arrangement that spaces them farther apart than in the liquid."},{"label":"B","text":"On freezing, hydrogen bonds add extra bonding mass to each \\(\\text{H}_2\\text{O}\\) molecule without changing how the molecules are spaced."},{"label":"C","text":"On freezing, hydrogen bonds draw the \\(\\text{H}_2\\text{O}\\) molecules into closer contact so they pack more tightly than in the liquid."},{"label":"D","text":"On freezing, the slowing of molecular motion lets the \\(\\text{H}_2\\text{O}\\) molecules settle closer together, an effect hydrogen bonds do not oppose."}]$op79$::jsonb,
    'A',
    $ex79$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is A because, as OpenStax describes for water, the extensive hydrogen bonding present in ice holds the \(\text{H}_2\text{O}\) molecules in a more open arrangement than exists in the liquid; spacing the molecules farther apart spreads the same mass over a larger volume, so the solid has a lower density (about \(0.92\ \text{g/cm}^3\)) than the liquid (about \(1.0\ \text{g/cm}^3\)) and floats. Density is mass per unit volume, so the lower density of ice must come from the molecules occupying more space, not from any change in the molecules' mass. (Choice B) A hydrogen bond is an intermolecular attraction between an \(\text{H}\) bonded to \(\text{N}\), \(\text{O}\), or \(\text{F}\) and a lone pair on a neighboring electronegative atom; it does not add mass to a molecule, and because the molecular mass is unchanged on freezing, an unchanged spacing would leave the density unchanged rather than lowered. (Choice C) This inverts the actual structural effect: hydrogen bonding in ice produces a more open, not a more tightly packed, arrangement, and closer packing would raise the density above that of the liquid, making the solid sink rather than float. (Choice D) Although molecular motion does slow on freezing, in most substances closer packing in the solid does raise density above the liquid; for water the hydrogen bonds specifically resist this by holding the molecules in the open arrangement, which is precisely why ice is less dense than liquid water. Skill 2$ex79$,
    'hard', '5B', $cc79$Nature of molecules and intermolecular interactions$cc79$, 'general-chemistry', 2, 160
  ) RETURNING id
)
