UNION ALL SELECT id, 'C', 'misconception', $a81C$Mistaking a polar covalent bond for an ionic attraction and conflating intramolecular bonds with intermolecular forces$a81C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a81D$Asserting permanent dipoles always outweigh dispersion forces$a81D$ FROM q;

-- Q16 [Intermolecular Forces · medium · Skill 2 · general-chemistry · ans C] (g82)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Intermolecular Forces',
    $qt82$The diatomic halogens \(\text{F}_2\), \(\text{Cl}_2\), \(\text{Br}_2\), and \(\text{I}_2\) are all nonpolar. At \(1\,\text{atm}\), which one has the highest normal boiling point, and why?$qt82$,
    $op82$[{"label":"A","text":"\\(\\text{F}_2\\), because fluorine is the most electronegative halogen and therefore holds its electrons most tightly, giving the strongest intermolecular attractions."},{"label":"B","text":"\\(\\text{Cl}_2\\), because the small \\(\\Delta\\text{EN}\\) within the molecule produces dipole-dipole forces that peak near the middle of the group."},{"label":"C","text":"\\(\\text{I}_2\\), because its large, easily polarized electron cloud gives the strongest London dispersion forces among the four."},{"label":"D","text":"\\(\\text{I}_2\\), because its high molar mass is itself the property that determines the strength of the intermolecular forces."}]$op82$::jsonb,
    'C',
    $ex82$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is C because \(\text{I}_2\) has the largest, most easily distorted electron cloud, so it experiences the strongest London dispersion forces and thus the highest boiling point. All four halogens are homonuclear and nonpolar, so the only intermolecular force available is London dispersion; the strength of dispersion forces rises with polarizability, which increases with the size of the electron cloud, so the boiling points climb in the order \(\text{F}_2 < \text{Cl}_2 < \text{Br}_2 < \text{I}_2\) (from roughly \(-188\,^\circ\text{C}\) to about \(+184\,^\circ\text{C}\)). (Choice A) Electronegativity governs polarity within a heteronuclear bond, not the attraction between identical nonpolar molecules, and tighter electron binding lowers polarizability, so this reasoning predicts the boiling-point trend in the reverse of the observed direction. (Choice B) A homonuclear \(\text{Cl}_2\) molecule has \(\Delta\text{EN}=0\) and no net molecular dipole, so dipole-dipole forces do not operate between \(\text{Cl}_2\) molecules at all. (Choice D) The heaviest halogen does have the highest boiling point, but molar mass only correlates with the trend; the causal factor is the larger, more polarizable electron cloud that accompanies the heavier atom, not the mass itself. Skill 2$ex82$,
    'medium', '5B', $cc82$Nature of molecules and intermolecular interactions$cc82$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
