UNION ALL SELECT id, 'B', 'misconception', $a90B$Treating rotamers (conformational isomers) as distinct constitutional isomers$a90B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a90C$Mistaking enantiomers (a stereoisomer subtype) for constitutional isomers$a90C$ FROM q;

